def page(title,desc,active,body,pageclass='',js3d=False):
    structured='<script type="application/ld+json">'+json.dumps(SCHEMA,ensure_ascii=False).replace('<','\\u003c')+'</script>'
    script3d='<script defer src="assets/joinery-3d.js"></script>' if js3d else ''
    html=f'''<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#111d22"><meta name="color-scheme" content="light"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:site_name" content="Dhanushree Timbers & Furnitures"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="preconnect" href="https://images.pexels.com"><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="stylesheet" href="assets/site.css">{structured}</head><body class="{pageclass}">{header(active)}<main id="main">{body}</main>{footer()}<script defer src="assets/site.js"></script>{script3d}</body></html>'''
    (ROOT/active).write_text(html,encoding='utf-8')
    print(f'{active}: {len(html):,} chars')

